  const answerFields = {"本科背景要求": "background", "CGPA / 学术要求": "cgpa", "英语要求": "language", "工作经验要求": "experience", "学制": "duration", "入学时间": "intake", "学费": "fee"};
  let dataPromise;
  function data() {
    if (!dataPromise) dataPromise = (async () => {
      if (typeof DecompressionStream !== 'function') throw new Error('请使用新版 Safari、Chrome 或 Edge 打开网站。');
      const bytes = Uint8Array.from(atob(encoded), char => char.charCodeAt(0));
      const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
      const result = await new Response(stream).json();
      result.byFile = new Map(result.catalog.programmes.map((row, i) => [row.file_path, { ...result.details[i], ...row }]));
      window.knowledgeDataDate = result.catalog.exported_at;
      return result;
    })().catch(error => { dataPromise = null; throw error; });
    return dataPromise;
  }
  window.hostedKB = async url => {
    const parsed = new URL(url, 'https://query.local'), loaded = await data();
    if (parsed.pathname === '/api/search') {
      const rows = knowledgeSearch(loaded.catalog, parsed.searchParams.get('q') || '', Object.fromEntries(parsed.searchParams));
      for (const row of rows) if (row.requested_field) {
        const key = answerFields[row.requested_field];
        row.answer = loaded.byFile.get(row.file_path)?.summaries[key] || '';
      }
      return rows;
    }
    if (parsed.pathname === '/api/programme') {
      const row = loaded.byFile.get(parsed.searchParams.get('file'));
      if (!row) throw new Error('专业不存在，请刷新页面。');
      return { ...row };
    }
    throw new Error('查询地址无效。');
  };
